            <button class="nav-tab" onclick="showDirection(2)">2. Dense Intelligence</button>
            <button class="nav-tab" onclick="showDirection(3)">3. Conversational Warmth</button>
            <button class="nav-tab" onclick="showDirection(4)">4. Enterprise Command</button>
            <button class="nav-tab" onclick="showDirection(5)">5. Mobile First</button>
            <button class="nav-tab" onclick="showDirection(6)">6. Gradient Energy</button>
