import { useState, useEffect } from 'react';

const ResponsiveImage = ({ src, alt }) => {
  const [imageSrc, setImageSrc] = useState(src.mobile);

  useEffect(() => {
    const updateImage = () => {
      if (window.innerWidth >= 1024) setImageSrc(src.desktop);
      else if (window.innerWidth >= 768) setImageSrc(src.tablet);
      else setImageSrc(src.mobile);
    };

    updateImage();
    window.addEventListener('resize', updateImage);
    return () => window.removeEventListener('resize', updateImage);
  }, [src]);

  return <img src={imageSrc} alt={alt} loading="lazy" />;
};
